UPDATE pages SET content = '<style> .alojamientos-grid {     display: grid;     grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));     gap: 2rem;     margin-top: 2rem; } .alojamiento-card {     background: #fff;     border: 1px solid rgba(0,0,0,0.18);     border-radius: 12px;     overflow: hidden;     box-shadow: 0 4px 15px rgba(0,0,0,0.05);     transition: transform 0.3s ease, box-shadow 0.3s ease, border-color 0.3s ease;     display: flex;     flex-direction: column; } .alojamiento-card:hover {     transform: translateY(-5px);     box-shadow: 0 10px 25px rgba(0,0,0,0.15);     border-color: rgba(0,0,0,0.35); } .alojamiento-img-container {     width: 100%;     height: 200px;     overflow: hidden;     position: relative; } .alojamiento-img-container img {     width: 100%;     height: 100%;     object-fit: cover;     transition: transform 0.5s ease; } .alojamiento-card:hover .alojamiento-img-container img {     transform: scale(1.05); } .alojamiento-content {     padding: 1.5rem;     flex-grow: 1;     display: flex;     flex-direction: column; } .alojamiento-title {     font-size: 1.25rem;     font-weight: 700;     color: var(--primary, #2c3e50);     margin-bottom: 0.5rem;     text-align: center; } .alojamiento-type {     font-size: 0.85rem;     color: var(--accent, #e67e22);     text-transform: uppercase;     font-weight: 600;     text-align: center;     margin-bottom: 1rem;     letter-spacing: 1px; } .alojamiento-phones {     margin-bottom: 1.5rem;     flex-grow: 1; } .alojamiento-phone {     display: flex;     align-items: center;     gap: 0.5rem;     margin-bottom: 0.4rem;     color: #555;     font-size: 0.95rem; } .alojamiento-phone i {     color: var(--primary, #2c3e50);     width: 20px;     text-align: center; } .alojamiento-btn {     display: block;     width: 100%;     padding: 0.8rem;     background: var(--primary, #2c3e50);     color: white !important;     text-align: center;     border-radius: 6px;     text-decoration: none;     font-weight: 600;     transition: background 0.3s ease; } .alojamiento-btn:hover {     background: var(--primary-dark, #1a252f); } /* Keywords hidden for SEO as in original */ .seo-keywords {     font-size: 0.7rem;     color: transparent;     opacity: 0.05;     user-select: none;     margin-top: 3rem; } </style>  <div class="alojamientos-grid">     <!-- Pepe el Pintor -->     <div class="alojamiento-card">         <div class="alojamiento-img-container">             <img src="images/100_1018.jpg" alt="Casas de campo Pepe el Pintor">         </div>         <div class="alojamiento-content">             <div class="alojamiento-type">Casas de campo</div>             <h3 class="alojamiento-title">"PEPE EL PINTOR"</h3>             <div class="alojamiento-phones">                 <div class="alojamiento-phone"><i class="fas fa-phone-alt"></i> +34 968 730 266</div>                 <div class="alojamiento-phone"><i class="fas fa-mobile-alt"></i> +34 610 254 834</div>                 <div class="alojamiento-phone"><i class="fas fa-mobile-alt"></i> +34 678 677 119</div>             </div>             <a href="https://www.moratalla-murcia.com/casaspepepintor" target="_blank" class="alojamiento-btn">Ver Alojamiento</a>         </div>     </div>      <!-- Villa Juana -->     <div class="alojamiento-card">         <div class="alojamiento-img-container">             <img src="images/ext_juana.jpg" alt="Casas de campo Villa Juana">         </div>         <div class="alojamiento-content">             <div class="alojamiento-type">Casas de campo</div>             <h3 class="alojamiento-title">"VILLA JUANA"</h3>             <div class="alojamiento-phones">                 <div class="alojamiento-phone"><i class="fas fa-phone-alt"></i> +34 968 706 217</div>                 <div class="alojamiento-phone"><i class="fas fa-mobile-alt"></i> +34 679 913 408</div>             </div>             <a href="https://www.moratalla-murcia.com/casasvillajuana" target="_blank" class="alojamiento-btn">Ver Alojamiento</